//! 🧪️ Two original UI roots return unchanged before private merged arguments can leave their actual continuation.
use super::*;
use semio_framework_job::*;
use semio_framework_value::{DslValue,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_ui_contract::{OriginalUiArguments,UiValue};
#[track_caller]
fn event(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:&mut dyn FnMut(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,|cx|run(cx)));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"UI argument continuation receipt {p:?} failure={:?}",result.as_ref().err());result.unwrap()}
fn denials(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut result=Vec::new();for axis in 0..5{let mut q=g;match axis{0=>q.maximum_items=0,1 if d.copy_bytes>0=>q.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>q.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>q.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>q.maximum_depth=d.depth-1,_=>continue}result.push(q)}result}
fn bounded(value:&mut serde_json::Value){match value{serde_json::Value::String(text)=>text.truncate(510),serde_json::Value::Array(rows)=>rows.iter_mut().for_each(bounded),serde_json::Value::Object(rows)=>rows.values_mut().for_each(bounded),_=>{}}}
fn retire_ui(value:Option<UiValue>){if let Some(value)=value{let mut close=semio_framework_ui_contract::UiValueRetirement::new(value);while !close.terminal_is_empty(){close.close_step(1,64).unwrap();}}}
#[test]
fn original_ui_arguments_returns_both_source_slots_before_private_merge_handoff(){let mut law:serde_json::Value=serde_json::from_str(include_str!("../../🔀️merge/🧪️tests/🔣️.json")).unwrap();bounded(&mut law);let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};for row in law["cases"].as_array().unwrap(){for cut in [Some(0),Some(1),Some(4),Some(15),Some(70),Some(250),None]{let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut args=(!row["args"].is_null()).then(||serde_json::from_value::<UiValue>(row["args"].clone()).unwrap());let mut input=(!row["input"].is_null()).then(||serde_json::from_value::<UiValue>(row["input"].clone()).unwrap());let mut owner=None;for denied in denials(g,OriginalUiArguments::birth_demands()){event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!OriginalUiArguments::admit(&mut args,&mut input,cx,&mut owner)?);Ok(())});assert!(owner.is_none());}event(&mut caller,&mut decoder,g,&mut|cx|{assert!(OriginalUiArguments::admit(&mut args,&mut input,cx,&mut owner)?);Ok(())});let active=owner.as_mut().unwrap();let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,g,&mut|cx|{assert!(active.advance(&mut args,&mut input,cx).is_err());Ok(())});let mut other=None;event(&mut caller,&mut decoder,g,&mut|cx|{assert!(active.advance(&mut other,&mut input,cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}if active.ready(){break}let Some(d)=active.demands(&args,&input).unwrap()else{continue};for denied in denials(g,d){event(&mut caller,&mut decoder,denied,&mut|cx|{active.advance(&mut args,&mut input,cx)?;Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(active.demands(&args,&input).unwrap(),Some(d));}event(&mut caller,&mut decoder,g,&mut|cx|{active.advance(&mut args,&mut input,cx)?;Ok(())});assert!(index<262143);}let mut output=None;if cut.is_none(){assert!(active.ready());assert_eq!(args.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or_default(),row["args"]);assert_eq!(input.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or_default(),row["input"]);for denied in denials(g,active.take_demands().unwrap()){event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!active.take_into(&mut output,cx)?);Ok(())});assert!(output.is_none()&&active.ready());}event(&mut caller,&mut decoder,g,&mut|cx|{assert!(active.take_into(&mut output,cx)?);Ok(())});assert_eq!(output.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or_default(),row["expected"]);}for index in 0..262144{if active.terminal_is_empty(){break}let d=active.close_demands().unwrap();for denied in denials(g,d){event(&mut caller,&mut decoder,denied,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(&mut args,&mut input,cx)?;Ok(())}));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.close_demands().unwrap(),d);}event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(&mut args,&mut input,cx)?;Ok(())}));assert!(index<262143);}assert_eq!(args.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or_default(),row["args"]);assert_eq!(input.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or_default(),row["input"]);event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=OriginalUiArguments::release_demands();close_original_retained_step(cx,d,|_|{owner.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();while output.is_some()||!close.is_empty(){event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<DslValue>(output.is_some(),&None,32768)?;close_original_retained_step(cx,d,|grant|if output.is_some(){Ok(close.begin_granted(&mut output,grant)?.unwrap())}else{close.select(32768)?.step(grant)})?;Ok(())}));}retire_ui(args);retire_ui(input);retire_decoder(&mut caller,&mut decoder);caller.retire(g);}}}
